export default {
  id: 'factor-base',
  name: 'Factor Base',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    ctx.register({
      kind: 'service',
      service: { id: 'factor', instance: { value: 7 } }
    });
  }
};

export default {
  id: 'factor-consumer',
  name: 'Factor Consumer',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    ctx.register({
      kind: 'command',
      command: {
        name: 'multiply',
        description: 'Return the factor service value multiplied by 5 as a string.',
        handler: async () => {
          const { value } = ctx.inject('service:factor') as { value: number };
          return String(value * 5);
        }
      }
    });
  }
};
